let sceneIndex=0;
const sceneBusy=job=>['submitting','queued','running','waiting'].includes(job?.status);
function currentScene(){return data.scenes?.[sceneIndex];}
function selectedSceneVersion(scene,key=scene.activeView||'master'){const versions=(scene.sceneVersions||[]).filter(v=>(v.view_key||'master')===key);return versions.find(v=>v.id===scene.activeVersions?.[key])||versions[versions.length-1];}
function confirmedSceneMaster(scene){return scene?selectedSceneVersion(scene,'master'):undefined;}
function sceneSize(scene){return scene.imageSize||data.sceneLibrary?.generation_rules?.default_resolution||{width:1280,height:720};}
function sceneCamera(scene,key){return key==='master'?'场景主参考图，广角建立镜头，展示场景整体空间布局。':(scene.camera_anchors||[]).find(c=>c.id===key)?.description||key;}
function sceneReference(scene,key){if(key!=='master'){const master=confirmedSceneMaster(scene);return{scene,version:master,required:true,reason:'请先生成本场景主图，再生成需要参考主图的其他机位。'};}const parent=sceneReferenceId(scene);if(parent){const reference=data.scenes.find(s=>s.id===parent);return{scene:reference,version:confirmedSceneMaster(reference),required:true,reason:'请先生成参考场景 '+parent+' 的主图。'};}if(scene.generation?.mode==='img2img'||scene.generation?.reference_image)return{required:true,reason:'请选择已生成主图的参考场景；JSON 路径不会被当作已存在的参考图片。'};return{required:false};}
function sceneWorldPrompt(){const library=data.sceneLibrary||{},layout=library.world_layout,world=library.shared_world||{};const names=data.characters.map(c=>c.name).filter(Boolean);const clean=value=>String(value||'').split(/[。；;\n]/).filter(t=>!names.some(n=>t.includes(n))&&!/弟子|剑气|剑光|反击|闪避|震退|断梁|碎裂|\d+(?:\.\d+)?秒/.test(t)).join('。');if(layout)return [library.generation_rules?.style,clean(typeof layout.weather==='string'?layout.weather:layout.weather?.type),...(layout.visual_anchors||[]).map(clean)].filter(Boolean).join('。');return [world.setting,world.visual_style,world.time?'时间：'+world.time:'',typeof world.weather==='string'?clean(world.weather):clean([world.weather?.type,world.weather?.intensity].filter(Boolean).join('，')),world.global_palette?.ambient?'环境光：'+world.global_palette.ambient:'',world.global_palette?.sunlight?'日光：'+world.global_palette.sunlight:'',...(world.continuity_rules||[]).map(clean)].filter(Boolean).join('。');}

const sceneImportDialog=document.createElement('dialog');sceneImportDialog.innerHTML='<div class="modal-head"><h2>导入场景库</h2><button id="closeSceneImport">✕</button></div><p>读取 scenes、共享世界、场景状态及连续性规则，按 scene_id 更新；保留已有生成版本。</p><label class="drop">选择场景 JSON 文件<input id="sceneFile" type="file" accept=".json,.txt,application/json" hidden></label><textarea id="sceneJson" rows="9" placeholder=\'{"project_id":"LAST_BATTERY_001","schema_type":"scene_library","scenes":[{"scene_id":"SC001","name":"场景名"}]}\'></textarea><p id="sceneImportStatus" role="status"></p><div class="modal-actions"><button id="checkSceneImport">检查文件</button><button id="applySceneImport" class="primary">导入场景</button></div>';document.body.append(sceneImportDialog);document.querySelector('#closeSceneImport').onclick=()=>sceneImportDialog.close();
function parseSceneText(){const raw=JSON.parse(document.querySelector('#sceneJson').value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));return{raw,parsed:SceneSchema.parse(raw,data.project_id)};}
function checkSceneFile(){const result=parseSceneText();document.querySelector('#sceneImportStatus').textContent='识别 '+result.parsed.scenes.length+' 个场景：'+result.parsed.scenes.map(s=>s.name).join('、')+'。点击「导入场景」保存。';return result.raw;}
function importScenes(raw){const result=SceneSchema.merge(data,raw);localStorage.setItem(key,JSON.stringify(result.project));data=result.project;sceneIndex=0;tab=1;save();render();toast(result.count+' 个场景已导入，原角色及分镜保留');}
document.querySelector('#checkSceneImport').onclick=()=>{try{checkSceneFile()}catch(e){document.querySelector('#sceneImportStatus').textContent=e.message}};
document.querySelector('#sceneFile').onchange=async e=>{const button=document.querySelector('#applySceneImport');button.disabled=true;try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('场景文件请小于 5 MB');document.querySelector('#sceneImportStatus').textContent='读取 '+file.name+'…';document.querySelector('#sceneJson').value=await file.text();checkSceneFile();e.target.value='';}catch(e){document.querySelector('#sceneImportStatus').textContent=e.message}finally{button.disabled=false}};
document.querySelector('#applySceneImport').onclick=()=>{try{importScenes(checkSceneFile());sceneImportDialog.close()}catch(e){document.querySelector('#sceneImportStatus').textContent='导入未完成：'+e.message}};
function openSceneImport(){document.querySelector('#sceneImportStatus').textContent='';sceneImportDialog.showModal();}
function exportScenes(){const blob=new Blob([JSON.stringify(SceneSchema.pack(data),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(data.title||'项目')+'-scenes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const importBeforeScenes=importProject;importProject=function(raw){if(raw?.schema_type==='scene_library'||raw?.type==='scenes'){importScenes(raw);document.querySelector('#importDialog').close();return}importBeforeScenes(raw)};
const exportSceneButton=document.createElement('button');exportSceneButton.textContent='04 场景 · 世界设定与参考图';exportSceneButton.onclick=exportScenes;document.querySelector('#moduleExports').append(exportSceneButton);
const sceneDetailsDialog=document.createElement('dialog');sceneDetailsDialog.style.width='760px';sceneDetailsDialog.innerHTML='<div class="modal-head"><h2 id="sceneDetailsTitle">场景详细设定</h2><button id="closeSceneDetails">✕</button></div><p class="subtle">修改有效 JSON 后自动保存；未完成的 JSON 不覆盖上次有效内容。</p><div id="sceneDetailsFields"></div>';document.body.append(sceneDetailsDialog);document.querySelector('#closeSceneDetails').onclick=()=>sceneDetailsDialog.close();
function jsonSceneEditor(container,object,property,label,fallback){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('textarea');input.rows=6;input.value=JSON.stringify(object[property]??fallback,null,2);const status=document.createElement('span');input.oninput=()=>{try{const value=JSON.parse(input.value);if(!value||typeof value!=='object')throw Error();if(Array.isArray(fallback)!==Array.isArray(value))throw Error();object[property]=value;status.textContent='已保存';save();}catch{status.textContent='格式未完成，保留上次有效内容。'}};wrap.append(input,status);container.append(wrap);}
function openSceneDetails(world=false){const box=document.querySelector('#sceneDetailsFields');box.replaceChildren();document.querySelector('#sceneDetailsTitle').textContent=world?'共享世界与连续性设定':'场景详细设定';if(world){data.sceneLibrary??={};for(const [property,label,fallback] of [['world_layout','街区布局与场景联系',{}],['variant_template','新机位模板',{}],['shared_world','共享世界',{}],['coordinate_system','坐标系',{}],['scene_states','场景状态',[]],['generation_rules','生成规则',{}]])jsonSceneEditor(box,data.sceneLibrary,property,label,fallback);}else{const scene=currentScene();for(const [property,label,fallback] of [['environment','环境与固定地标',{}],['zones','空间分区',[]],['camera_anchors','机位',[]],['connected_to','连接场景',[]],['reference_images','参考图路径',{}]])jsonSceneEditor(box,scene,property,label,fallback);}sceneDetailsDialog.showModal();}
function sceneField(id,label,value,rows=0){return field(label,id,value,rows);}
function renderScenes(){data.scenes??=[];if(sceneIndex>=data.scenes.length)sceneIndex=0;const scene=currentScene();const parent=scene?.environment?.parent_scene_id;document.querySelector('#panel').innerHTML=`<div class="section-head"><div><h3>搭建故事发生的世界</h3><p>共享街区与光照设定，先确认主图，再生成不同机位。</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button id="sceneImport">↓ 导入场景 JSON</button><button id="sceneExport">导出场景</button><button id="sceneWorld">共享世界</button><button id="sceneAdd">＋ 添加场景</button></div></div>${!scene?'<div class="card empty-stage"><h3>还没有场景</h3><p>导入 scenes.json，或添加第一个场景。</p></div>':`<div class="editor scene-editor"><div class="card"><div class="mini-label">场景库 / ${data.scenes.length}</div>${data.scenes.map((s,i)=>`<button data-scene="${i}" class="character-item ${i===sceneIndex?'selected':''}"><div><b>${esc(s.name)}</b><small>${esc(s.id)} · ${confirmedSceneMaster(s)?'主图已确认':'待确认'}</small></div></button>`).join('')}<div class="divider"></div><p class="subtle">${esc(data.sceneLibrary?.world_layout?.name||data.sceneLibrary?.shared_world?.setting||'可在共享世界中配置街区、天气和灯光。')}</p></div><div class="card"><div class="preview-head"><b id="scenePreviewTitle">场景预览</b><select id="sceneView" aria-label="场景机位" style="width:auto;max-width:65%;margin:0"><option value="master">主参考图</option>${(scene.camera_anchors||[]).map(a=>`<option value="${esc(a.id)}">${esc(a.id)} · ${esc(a.description)}</option>`).join('')}</select></div><div id="sceneImageBox" class="scene-image-box"></div><p id="sceneJobStatus" class="subtle" role="status"></p><div style="display:flex;gap:8px;flex-wrap:wrap"><button id="sceneConfirm">✓ 确认场景主图</button><a id="sceneImageDownload" style="color:var(--green);align-self:center" download>下载图片</a></div><p id="sceneReferenceStatus" class="subtle"></p><div class="divider"></div><div class="mini-label">当前机位历史版本</div><div id="sceneVersions" class="history"></div><div id="sceneWorkflowLinks" style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px;font-size:11px"></div></div><div class="card"><div class="right-title" style="display:flex;justify-content:space-between">场景设定<button id="sceneDelete" class="text" style="color:#f1b6b6;font-size:10px">删除场景</button></div><div class="field-row">${sceneField('sceneName','名称',scene.name)}<label>场景 ID<input value="${esc(scene.id)}" readonly></label></div>${sceneField('scenePurpose','剧情作用',scene.purpose||'',3)}<button id="sceneDetails" class="wide">环境、分区与机位设定</button><div class="divider"></div>${sceneField('scenePrompt','场景提示词',scene.prompt,6)}${sceneField('sceneNegative','负面提示词',scene.negativePrompt,3)}<p class="subtle">负面词已连接采样器：Turbo 主图采用低强度 CFG 1.5（试用）；Qwen 编辑采用 CFG 4、12步。</p><label>参考场景<select id="sceneReference" ${parent?'disabled':''}><option value="">独立建立场景</option>${data.scenes.filter(s=>s.id!==scene.id).map(s=>`<option value="${esc(s.id)}">${esc(s.id)} · ${esc(s.name)}</option>`).join('')}</select></label><p class="subtle">${parent?'该场景属于 '+esc(parent)+' 的局部，必须引用它已确认的主图。':'选择参考场景可使用图像编辑。其他机位使用本场景当前主图。'}</p><div class="field-row">${sceneField('sceneWidth','宽度 px',sceneSize(scene).width)}${sceneField('sceneHeight','高度 px',sceneSize(scene).height)}</div><button id="sceneGenerate" class="primary wide">生成场景图</button><p class="subtle">空场景参考图；角色与动态道具在分镜环节加入。文字与图像参考可以减少变化，仍需检查建筑和地标一致性。</p></div></div>`}`;
document.querySelector('#sceneImport').onclick=openSceneImport;document.querySelector('#sceneExport').onclick=exportScenes;document.querySelector('#sceneWorld').onclick=()=>openSceneDetails(true);document.querySelector('#sceneAdd').onclick=()=>{let n=1;while(data.scenes.some(s=>s.id==='SC'+String(n).padStart(3,'0')))n++;const id='SC'+String(n).padStart(3,'0');data.scenes.push(SceneSchema.normalize({scene_id:id,name:'新场景',environment:{},zones:[],camera_anchors:[],connected_to:[],generation:{positive_prompt:'',negative_prompt:''}},0));sceneIndex=data.scenes.length-1;save();render()};if(!scene)return;document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{sceneIndex=Number(b.dataset.scene);render()});for(const [id,property] of [['sceneName','name'],['scenePurpose','purpose'],['scenePrompt','prompt'],['sceneNegative','negativePrompt']])document.querySelector('#'+id).oninput=e=>{scene[property]=e.target.value;if(property==='prompt'||property==='negativePrompt'){scene.generation??={};scene.generation[property==='prompt'?'prompt':'negative_prompt']=e.target.value;}save();};document.querySelector('#sceneDetails').onclick=()=>openSceneDetails();document.querySelector('#sceneView').value=scene.activeView||'master';document.querySelector('#sceneView').onchange=e=>{scene.activeView=e.target.value;save();render()};document.querySelector('#sceneReference').value=sceneReferenceId(scene)||'';document.querySelector('#sceneReference').onchange=e=>{scene.referenceSceneId=e.target.value;scene.generation??={};scene.generation.reference_scene_id=e.target.value||undefined;scene.generation.mode=e.target.value?'img2img':'txt2img';scene.generation.reference_image=e.target.value?(data.scenes.find(s=>s.id===e.target.value)?.generation?.output_image||'assets/scenes/'+e.target.value+'/master.png'):null;save();render()};for(const [id,property] of [['sceneWidth','width'],['sceneHeight','height']]){const input=document.querySelector('#'+id);input.type='number';input.min=256;input.max=1536;input.step=16;input.oninput=()=>{scene.imageSize??=sceneSize(scene);scene.imageSize[property]=Number(input.value);save();};}document.querySelector('#sceneGenerate').onclick=()=>generateScene(scene);document.querySelector('#sceneConfirm').onclick=()=>{const version=selectedSceneVersion(scene,'master');if(version){scene.confirmedMasterJobId=version.id;save();render();toast('场景主图已确认')}};document.querySelector('#sceneDelete').onclick=()=>{if(Object.values(scene.jobs||{}).some(sceneBusy)){toast('请等待该场景生成任务结束');return}if(!confirm('将场景「'+scene.name+'」移入场景回收站？原图片保留。'))return;data.sceneTrash??=[];data.sceneTrash.push(clone(scene));data.scenes.splice(sceneIndex,1);sceneIndex=0;save();render()};updateScenePreview(scene);}
function updateScenePreview(scene){const key=scene.activeView||'master',version=selectedSceneVersion(scene,key),job=scene.jobs?.[key],reference=sceneReference(scene,key),busy=sceneBusy(job);const box=document.querySelector('#sceneImageBox');if(!box)return;box.replaceChildren();if(version?.image_url){const a=document.createElement('a');a.href=version.image_url;a.target='_blank';const img=document.createElement('img');img.src=version.image_url;img.alt=scene.name+' · '+sceneCamera(scene,key);a.append(img);box.append(a);}else{const placeholder=document.createElement('div');placeholder.className='empty-stage';placeholder.innerHTML='<div class="stage-icon">▧</div><p>该机位尚未生成</p>';box.append(placeholder);}document.querySelector('#scenePreviewTitle').textContent=scene.name;document.querySelector('#sceneJobStatus').textContent=job?({submitting:'正在提交场景任务…',queued:'已进入 ComfyUI 队列',running:'正在生成场景图…',waiting:'等待生成结果',completed:'场景图已生成并保存到本机',failed:'生成失败：'+job.error})[job.status]||job.status:'编辑设定后开始生成';const generate=document.querySelector('#sceneGenerate');generate.disabled=busy||!!(reference.required&&!reference.version);generate.textContent=busy?'正在生成…':version?'重新生成当前机位':'生成当前机位';const confirmButton=document.querySelector('#sceneConfirm');confirmButton.style.display='none';confirmButton.disabled=key!=='master'||!version||busy;confirmButton.textContent=version&&version.id===scene.confirmedMasterJobId?'✓ 主图已确认':'✓ 确认场景主图';const download=document.querySelector('#sceneImageDownload');download.style.display=version?'':'none';if(version)download.href=version.image_url;const refText=document.querySelector('#sceneReferenceStatus');const refMessage=reference.required?(reference.version?'当前参考：'+reference.scene.name+' · 当前主图':reference.reason):'主图使用共享世界设定建立；场景参考图片路径仅记录，不会自动读取外部文件。';refText.textContent=refMessage+(version&&key!=='master'&&version.reference_job_id!==confirmedSceneMaster(scene)?.id?' 当前机位基于旧主图，建议重新生成。':'');const historyBox=document.querySelector('#sceneVersions');historyBox.replaceChildren();for(const [i,v] of (scene.sceneVersions||[]).filter(v=>(v.view_key||'master')===key).entries()){const button=document.createElement('button');button.textContent='V'+(i+1)+' · '+new Date(v.finished_at||v.created_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});if(version?.id===v.id)button.className='primary';button.onclick=()=>{scene.activeVersions??={};scene.activeVersions[key]=v.id;save();render()};historyBox.append(button)}const links=document.querySelector('#sceneWorkflowLinks');links.replaceChildren();const workflowId=job?.prompt_id?job.id:version?.id;if(workflowId){for(const [label,suffix] of [['查看实际工作流',''],['下载工作流','?download=1']]){const a=document.createElement('a');a.textContent=label;a.href='/api/front-image/'+workflowId+'/workflow'+suffix;a.target='_blank';a.style.color='var(--green)';links.append(a)}}}
function applySceneJob(scene,key,job){scene.jobs??={};scene.jobs[key]=job;if(job.status==='completed'&&!scene.sceneVersions.some(v=>v.id===job.id)){scene.sceneVersions.push(job);scene.activeVersions??={};scene.activeVersions[key]=job.id;scene.reference_images??={};scene.reference_images[key]=job.image_url;}save();}
const sceneSubmitting=new Set();async function generateScene(scene){const view=scene.activeView||'master';if(sceneSubmitting.has(scene.id+view)||sceneBusy(scene.jobs?.[view]))return;const size=sceneSize(scene);if(![size.width,size.height].every(n=>Number.isInteger(n)&&n>=256&&n<=4096)||size.width*size.height>8388608){toast('场景尺寸需为256–4096之间的整数，总像素不超过约839万');return}if(!scene.prompt.trim()){toast('请先填写场景提示词');return}const reference=sceneReference(scene,view);if(reference.required&&!reference.version){toast(reference.reason);return}const id=crypto.randomUUID(),lock=scene.id+view;sceneSubmitting.add(lock);scene.jobs??={};scene.jobs[view]={id,status:'submitting',view_key:view};save();render();try{const job=await frontFetch('/api/front-image',{request_id:id,port:Number(localStorage.getItem('frame-comfy-port')||8188),resource_type:'scene',edit_intent:scene.editIntent||'build',model:scene.imageModel||'qwen',denoise:Number(scene.denoise??0.45),mode:reference.version?'scene_edit':'front',reference_job_id:reference.version?.id,project_id:data.project_id||data.title,character_id:scene.id,character_name:scene.name,view_key:view,prompt:scene.prompt,negative_prompt:scene.negativePrompt,world_prompt:sceneWorldPrompt(),view_prompt:(view==='master'?'':(data.sceneLibrary?.variant_template?.prompt_template||'')+'。')+sceneCamera(scene,view),...size});applySceneJob(scene,view,job);toast('场景任务已提交到本机 ComfyUI')}catch(e){scene.jobs[view]={id,status:'failed',error:e.message};save();toast('提交失败：'+e.message)}finally{sceneSubmitting.delete(lock);if(tab===1)render()}}
let checkingScenes=false;setInterval(async()=>{if(checkingScenes)return;checkingScenes=true;let changed=false;try{for(const scene of data.scenes||[])for(const [view,job] of Object.entries(scene.jobs||{})){if(!['queued','running','waiting'].includes(job.status))continue;try{const latest=await frontFetch('/api/front-image/'+job.id);applySceneJob(scene,view,latest);changed=true;}catch(e){job.last_connection_error=e.message;}}if(changed&&tab===1)render();}finally{checkingScenes=false}},3000);
const stageBeforeScenes=stage;stage=function(){if(tab===1)renderScenes();else stageBeforeScenes()};document.querySelector('.notice').textContent='✦ 角色与场景生图已接入本机 ComfyUI；分镜、视频等后续环节仍在完善。';render();

const sceneTrashDialog=document.createElement('dialog');sceneTrashDialog.innerHTML='<div class="modal-head"><h2>场景回收站</h2><button id="closeSceneTrash">✕</button></div><div id="sceneTrashItems"></div>';document.body.append(sceneTrashDialog);document.querySelector('#closeSceneTrash').onclick=()=>sceneTrashDialog.close();function openSceneTrash(){const box=document.querySelector('#sceneTrashItems');box.replaceChildren();const list=data.sceneTrash||[];if(!list.length)box.textContent='暂无已删除场景。';for(const scene of list){const row=document.createElement('div');row.className='card';const name=document.createElement('p');name.textContent=scene.id+' · '+scene.name;const restore=document.createElement('button');restore.textContent='恢复场景';restore.onclick=()=>{if(data.scenes.some(s=>s.id===scene.id)){toast('当前已有同 ID 场景，请先处理重复场景');return}data.scenes.push(clone(scene));data.sceneTrash=data.sceneTrash.filter(s=>s.id!==scene.id);save();sceneTrashDialog.close();render()};row.append(name,restore);box.append(row)}sceneTrashDialog.showModal();}const renderScenesWithTrash=renderScenes;renderScenes=function(){renderScenesWithTrash();const button=document.createElement('button');button.textContent='场景回收站';button.onclick=openSceneTrash;document.querySelector('#sceneAdd')?.parentElement.append(button)};
const overviewBeforeSceneCount=overview;overview=function(){overviewBeforeSceneCount();let count=document.querySelector('#sceneCount');if(!count){count=document.createElement('span');count.id='sceneCount';document.querySelector('.overview-bottom').append(count)}count.textContent='⌂ '+(data.scenes?.length||0)+' 个场景';};render();

function sceneReferenceId(scene){return scene.referenceSceneId??scene.generation?.reference_scene_id??scene.environment?.parent_scene_id??'';}
function sceneSpatialLinks(scene){return scene.environment?.spatial_links||scene.connected_to||[];}
function sceneLinkId(link){return typeof link==='string'?link:link.scene_id||link.target_scene_id||link.target||'';}
const renderScenesBeforeRelations=renderScenes;
renderScenes=function(){renderScenesBeforeRelations();if(!data.scenes?.length)return;const panel=document.querySelector('#panel'),world=data.sceneLibrary?.world_layout||{};const box=document.createElement('div');box.className='card scene-relations';box.innerHTML=`<div class="preview-head"><b>场景联系 · ${esc(world.name||'同一故事世界')}</b><span class="subtle">点击场景切换</span></div><p class="subtle">${esc(world.continuity||'空间连接表示相邻地点；生成参考表示下一张图使用哪张当前主图。')}</p><div class="scene-relation-list">${data.scenes.map((s,i)=>{const ref=sceneReferenceId(s),source=data.scenes.find(x=>x.id===ref),ready=confirmedSceneMaster(source);return `<button data-relation-scene="${i}" class="scene-relation-node ${sceneIndex===i?'active':''}"><small>${esc(s.id)} · ${ref||s.generation?.mode==='img2img'?'图生图':'文生图'}</small><b>${esc(s.name)}</b><span>${ref?'← 参考 '+esc(source?.name||ref)+(ready?' · 已就绪':' · 待生成主图'):'起始场景 · 独立生成'}</span></button>`}).join('')}</div><div id="sceneSpatialConnections" class="subtle"></div></div>`;panel.querySelector('.section-head').after(box);box.querySelectorAll('[data-relation-scene]').forEach(b=>b.onclick=()=>{sceneIndex=Number(b.dataset.relationScene);render()});const edges=new Set();const labels=[];for(const s of data.scenes)for(const link of sceneSpatialLinks(s)){const id=sceneLinkId(link),target=data.scenes.find(x=>x.id===id);if(!id)continue;const edge=[s.id,id].sort().join('|');if(edges.has(edge))continue;edges.add(edge);labels.push(s.name+' ↔ '+(target?.name||id));}box.querySelector('#sceneSpatialConnections').textContent='空间相邻：'+(labels.join('　 /　 ')||'未配置');};
render();
const scenePreviewBeforeInspectionLinks=updateScenePreview;
updateScenePreview=function(scene){scenePreviewBeforeInspectionLinks(scene);const key=scene.activeView||'master',version=selectedSceneVersion(scene,key),job=scene.jobs?.[key],reference=sceneReference(scene,key);const workflowJob=sceneBusy(job)&&job.prompt_id?job:version?.id?version:job?.prompt_id?job:null;const links=document.querySelector('#sceneWorkflowLinks');links.replaceChildren();links.style.marginTop='12px';const template='/api/front-image-template'+(reference.required?'?mode=multiview':'');const items=workflowJob? [['查看当前生成工作流','/api/front-image/'+workflowJob.id+'/workflow'],['下载工作流','/api/front-image/'+workflowJob.id+'/workflow?download=1']]:[['查看场景工作流模板',template],['下载模板',template+(template.includes('?')?'&':'?')+'download=1']];if(version?.image_url)items.push(['打开生成图片',version.image_url]);items.push(['打开 ComfyUI','http://127.0.0.1:'+Number(localStorage.getItem('frame-comfy-port')||8188)+'/']);for(const [label,url] of items){const a=document.createElement('a');a.textContent=label;a.href=url;a.target='_blank';a.rel='noopener';a.style.color='var(--green)';links.append(a)}document.querySelector('#sceneGenerate').after(links);};
render();

const renderScenesBeforeModel=renderScenes;
renderScenes=function(){renderScenesBeforeModel();const scene=currentScene();if(!scene)return;const label=document.createElement('label');label.textContent='场景图生图模型';const select=document.createElement('select');select.setAttribute('aria-label','场景图生图模型');for(const [value,text] of [['qwen','Qwen-Image-Edit · 参考图编辑'],['zimage','Z-Image · 图生图']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option)}select.value=scene.imageModel||'qwen';select.onchange=()=>{scene.imageModel=select.value;save();render()};label.append(select);const note=document.createElement('p');note.className='subtle';note.textContent=scene.imageModel==='zimage'?'Z-Image 图生图：以参考图编码为底图，12 步，可调整重绘强度。主图无参考时仍使用 Z-Image 文生图。':'Qwen 编辑参考图，12步、独立负面条件。主图无参考时使用 Z-Image 文生图。';document.querySelector('#sceneGenerate').before(label,note);};render();

const renderScenesBeforeDenoise=renderScenes;
renderScenes=function(){renderScenesBeforeDenoise();const scene=currentScene();if(!scene)return;const generate=document.querySelector('#sceneGenerate');if(scene.imageModel==='zimage'){const label=document.createElement('label');label.textContent='重绘强度（denoise）';const input=document.createElement('input');input.type='number';input.min='0.05';input.max='1';input.step='0.05';input.value=scene.denoise??0.45;input.setAttribute('aria-label','重绘强度（denoise）');input.onchange=()=>{const value=Number(input.value);if(!Number.isFinite(value)||value<0.05||value>1){toast('重绘强度需在 0.05–1 之间');input.value=scene.denoise??0.45;return}scene.denoise=value;save();};label.append(input);const hint=document.createElement('p');hint.className='subtle';hint.textContent='值越低越保留原图；值越高变化越大。此参数用于 Z-Image 图生图。';generate.before(label,hint);}const version=selectedSceneVersion(scene);if(version){const info=document.createElement('p');info.className='subtle';info.textContent='当前图片参数：'+(version.model==='zimage'?'Z-Image':version.mode==='scene_edit'?'Qwen-Image-Edit':'Z-Image')+(version.denoise!==undefined?' · denoise '+version.denoise:'')+' · '+(version.reference_job_id?'使用参考图':'文生图');generate.after(info);}};render();

const renderScenesBeforePreviewButton=renderScenes;
renderScenes=function(){renderScenesBeforePreviewButton();const button=document.querySelector('#sceneGenerate'),status=document.querySelector('#sceneJobStatus');if(!button||!status)return;let actions=document.querySelector('#scenePreviewGenerateActions');if(!actions){actions=document.createElement('div');actions.id='scenePreviewGenerateActions';actions.style.cssText='display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:14px 0';status.before(actions);}button.classList.remove('wide');button.style.cssText='width:auto;flex:none;padding:10px 20px';actions.append(button);const links=document.querySelector('#sceneWorkflowLinks');if(links)actions.after(links);};render();